import Foundation

/// What a task's agent was given to read, for the Context card: the context files where its threads start —
/// the ones Scope wrote under every name the installed drivers declare, and the repository's own — and the skills
/// the sandboxes hold.
///
/// Pure: the probes are injected, so a test runs on a hand-made tree and the app on the disk.
public enum TaskContextFiles {
    public enum Origin: Sendable, Equatable {
        /// Generated by Scope from the brief and the graph (`TaskProjection.generatedMarker` at its top).
        case writtenByScope
        /// Committed in the repository, or left there by the user: never touched by Scope.
        case repository
    }

    public struct Entry: Sendable, Equatable, Identifiable {
        public var url: URL
        public var origin: Origin
        /// Bytes on disk.
        public var size: Int
        /// The sandbox the file belongs to, for a task of several repositories; `nil` where the threads start.
        public var sandbox: String?

        public var id: String { url.path }
        public var name: String { url.lastPathComponent }

        public init(url: URL, origin: Origin, size: Int, sandbox: String? = nil) {
            self.url = url
            self.origin = origin
            self.size = size
            self.sandbox = sandbox
        }
    }

    /// What a probe says of one path: `nil` when there is no regular file there.
    public struct File: Sendable, Equatable {
        public var size: Int
        public var isGenerated: Bool

        public init(size: Int, isGenerated: Bool) {
            self.size = size
            self.isGenerated = isGenerated
        }
    }

    /// The names looked for in a directory: every name Scope writes for `declared` (`TaskManager.contextFileNames`)
    /// and the companion each may have gone to instead (`CLAUDE.local.md`), in that order.
    public static func names(declared: [String]) -> [String] {
        var names: [String] = []
        for name in TaskManager.contextFileNames(declared) {
            names.append(name)
            if let companion = TaskManager.companionContextFile[name] { names.append(companion) }
        }
        return names
    }

    /// The context files of a task: where its threads start first (`threadCwd`), then each other active sandbox
    /// (a task of several repositories, whose threads start at the root and see the sandboxes through `--add-dir`).
    /// In each place, Scope's own files come before the repository's. A path is listed once.
    public static func offered(task: TaskRecord, declared: [String],
                               probe: (URL) -> File?) -> [Entry] {
        var places: [(URL, String?)] = [(task.threadCwd, nil)]
        for repo in task.activeSandboxes where repo.sandboxURL.filesystemPath != task.threadCwd.filesystemPath {
            places.append((repo.sandboxURL, repo.sandboxKey))
        }
        var seen = Set<String>()
        var entries: [Entry] = []
        for (directory, sandbox) in places {
            var scopes: [Entry] = []
            var repos: [Entry] = []
            for name in names(declared: declared) {
                let url = directory.appending(path: name, directoryHint: .notDirectory)
                guard seen.insert(url.filesystemPath).inserted, let file = probe(url) else { continue }
                let entry = Entry(url: url, origin: file.isGenerated ? .writtenByScope : .repository, size: file.size, sandbox: sandbox)
                if file.isGenerated { scopes.append(entry) } else { repos.append(entry) }
            }
            entries += scopes + repos
        }
        return entries
    }

    /// Reads a path on disk for `offered`: a regular file's size, and whether Scope generated it.
    public static func diskProbe(_ url: URL) -> File? {
        guard let attributes = try? FileManager.default.attributesOfItem(atPath: url.path),
              (attributes[.type] as? FileAttributeType) == .typeRegular else { return nil }
        let size = (attributes[.size] as? NSNumber)?.intValue ?? 0
        return File(size: size, isGenerated: TaskManager.isGenerated(url))
    }

    /// `1.8 kB`, `6.1 kB`, `412 B`, `1.2 MB`.
    public static func sizeText(_ bytes: Int) -> String {
        let units: [(Double, String)] = [(1e6, "MB"), (1e3, "kB")]
        let value = Double(bytes)
        for (size, suffix) in units where value >= size {
            let scaled = value / size
            return (scaled < 9.95 ? String(format: "%.1f", scaled) : "\(Int(scaled.rounded()))") + " " + suffix
        }
        return "\(bytes) B"
    }

    // MARK: Skills

    /// The folder a driver loads skills from, under a repository: each subfolder holding a `SKILL.md` is one.
    public static let skillsFolder = ".claude/skills"

    /// The skills the task's sandboxes hold — copied from the base checkout at setup (`SandboxFileCopy.planResources`)
    /// or committed — by name, sorted, once each. `children` lists a folder's entries, `nil` when it is not one;
    /// `isSkill` says whether a folder is a skill (its `SKILL.md` exists).
    public static func skills(task: TaskRecord, children: (URL) -> [String]?, isSkill: (URL) -> Bool) -> [String] {
        var names = Set<String>()
        for repo in task.activeSandboxes {
            let folder = repo.sandboxURL.appending(path: skillsFolder, directoryHint: .isDirectory)
            for name in children(folder) ?? [] where !name.hasPrefix(".") {
                if isSkill(folder.appending(path: name, directoryHint: .isDirectory)) { names.insert(name) }
            }
        }
        return names.sorted()
    }

    public static func diskChildren(_ url: URL) -> [String]? {
        try? FileManager.default.contentsOfDirectory(atPath: url.path)
    }

    public static func diskIsSkill(_ url: URL) -> Bool {
        FileManager.default.fileExists(atPath: url.appending(path: "SKILL.md").path)
    }
}
